// generated by scripts/strings.mjs), so both apps say the same thing in every
// language. `web` holds the few sentences that only make sense here.
import strings from './strings.json' with { type: 'json' };

export type Lang = 'en' | 'fr' | 'he' | 'ru' | 'ar';

export const LANGS: { id: Lang; name: string }[] = [
  { id: 'en', name: 'English' },
  { id: 'fr', name: 'Français' },
  { id: 'he', name: 'עברית' },
  { id: 'ru', name: 'Русский' },
  { id: 'ar', name: 'العربية' },
];

export const isRTL = (lang: Lang) => lang === 'he' || lang === 'ar';

// Error codes sent by the API; the UI turns them into sentences.
export type ErrorCode =
  | 'INVALID_PASSWORD'
  | 'CHANGE_PASSWORD'
  | 'ACCOUNT_BLOCKED'
  | 'TIMEOUT'
  | 'BROWSER'
  | 'NO_ACCOUNT'
  | 'GENERIC'
  | 'FILL_BOTH'
  | 'NOT_SIGNED_IN'
  | 'SERVER_DOWN'
  | 'UNKNOWN';

