// The scraper's error codes, worded like the iPhone app's BankError messages.
const errorKeys: Record<ErrorCode, string> = {
  INVALID_PASSWORD: '%@ didn’t accept this username or password.',
  CHANGE_PASSWORD: '%@ asks you to change your password. Do it on their site, then sign in again.',
  ACCOUNT_BLOCKED: 'Your %@ account is blocked. Contact %@.',
  TIMEOUT: '%@ took too long to respond. The connection may be slow or the site busy: try again.',
  GENERIC: 'Couldn’t reach %@. Check your connection and try again.',
  BROWSER: 'BROWSER',
  NO_ACCOUNT: 'NO_ACCOUNT',
  FILL_BOTH: 'FILL_BOTH',
  NOT_SIGNED_IN: 'NOT_SIGNED_IN',
  SERVER_DOWN: 'SERVER_DOWN',
  UNKNOWN: 'UNKNOWN',
};

const catalog = strings as Record<string, Entry>;

/** A string in `lang`, with `%@` / `%lld` / `%1$lld` filled in order. */
export function L(lang: Lang, key: string, ...args: (string | number)[]): string {
  const entry = web[key] ?? catalog[key];
  let s: string | Record<string, string> = entry?.[lang] ?? entry?.en ?? key;
  if (typeof s === 'object') {
    const n = Number(args[0] ?? 0);
    s = s[new Intl.PluralRules(lang).select(n)] ?? s.other ?? key;
  }
  let next = 0;
  return s
    .replace(/%(\d)\$(?:lld|@)|%lld|%@/g, (_, pos) => String(pos ? args[Number(pos) - 1] : args[next++]))
    .replace(/%%/g, '%');
}

export function errorText(lang: Lang, code: string | undefined, name = ''): string {
  const key = errorKeys[(code as ErrorCode) ?? 'UNKNOWN'] ?? errorKeys.UNKNOWN;
  return L(lang, key, name, name);
}

export function detectLang(): Lang {
  try {
    const saved = localStorage.getItem('lang');
    if (LANGS.some((l) => l.id === saved)) return saved as Lang;
  } catch {}
  const device = typeof navigator === 'undefined' ? '' : navigator.language.toLowerCase().replace(/^iw/, 'he').slice(0, 2);
  return LANGS.some((l) => l.id === device) ? (device as Lang) : 'en';
}

const TZ = 'Asia/Jerusalem';
const locales: Record<Lang, string> = { en: 'en-IL', fr: 'fr-FR', he: 'he-IL', ru: 'ru-RU', ar: 'ar-IL-u-nu-latn' };

// Midnight in Israel: the bank only gave the day, not the time.
function hasTime(iso: string): boolean {
  const t = new Date(iso).toLocaleTimeString('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false });
  return t !== '00:00';
}

export function formatters(lang: Lang) {
  const loc = locales[lang];
  const shekel = new Intl.NumberFormat(loc, { style: 'currency', currency: 'ILS' });
  const whole = new Intl.NumberFormat(loc, { style: 'currency', currency: 'ILS', maximumFractionDigits: 0 });
  const percent = new Intl.NumberFormat(loc, { style: 'percent', maximumFractionDigits: 0 });
  const rtf = new Intl.RelativeTimeFormat(lang, { numeric: 'auto' });
  // A YYYY-MM-DD day stays that day whatever the visitor's time zone.
  const at = (iso: string) => (iso.length === 10 ? new Date(`${iso}T12:00:00Z`) : new Date(iso));
  const zone = (iso: string) => (iso.length === 10 ? 'UTC' : TZ);
  const fmt = (iso: string, o: Intl.DateTimeFormatOptions) => at(iso).toLocaleString(loc, { timeZone: zone(iso), ...o });
  const time = { hour: '2-digit', minute: '2-digit', hourCycle: 'h23' } as const;
  return {
    // Typographic minus, and never split the sign from the amount.
    ils: (n: number) => shekel.format(n === 0 ? 0 : n).replace('-', '−'), // n === 0 also catches −0
    ilsWhole: (n: number) => whole.format(n === 0 ? 0 : n).replace('-', '−'),
    money: (n: number, currency: string) =>
      new Intl.NumberFormat(loc, { style: 'currency', currency }).format(n).replace('-', '−'),
    percent: (n: number) => percent.format(n),
    /** "2 Nov" */
    day: (iso: string) => fmt(iso, { day: 'numeric', month: 'short' }),
    /** "2 Nov, 14:32" when the bank gave the time. */
    dayTime: (iso: string) =>
      iso.length > 10 && hasTime(iso) ? fmt(iso, { day: 'numeric', month: 'short', ...time }) : fmt(iso, { day: 'numeric', month: 'short' }),
    /** "Monday 2 November" */
    weekday: (iso: string) => fmt(iso, { weekday: 'long', day: 'numeric', month: 'long' }),
    /** "2 November 2026" */
    longDay: (iso: string) => fmt(iso, { day: 'numeric', month: 'long', year: 'numeric' }),
    /** "Monday 2 November 2026 at 14:32" when the bank gave the time. */
    fullDate: (iso: string) =>
      fmt(iso, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', ...(iso.length > 10 && hasTime(iso) ? time : {}) }),
    monthShort: (iso: string) => fmt(iso, { month: 'narrow' }),
    ago: (iso: string) => {
      const minutes = Math.round((new Date(iso).getTime() - Date.now()) / 60_000);
      if (Math.abs(minutes) < 60) return rtf.format(minutes, 'minute');
      const hours = Math.round(minutes / 60);
      if (Math.abs(hours) < 24) return rtf.format(hours, 'hour');
      return rtf.format(Math.round(hours / 24), 'day');
    },
  };
}
